def transform(grid):
    from collections import Counter
    flat = [v for row in grid for v in row]
    bg = Counter(flat).most_common(1)[0][0]
    color = next(v for v in set(flat) if v != bg)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == color]
        if len(xs) >= 3:
            for c in range(min(xs), max(xs) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == color]
        if len(ys) >= 3:
            for r in range(min(ys), max(ys) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
